# GMAT Focus Data Insights (on-screen calculator allowed).
# Per test: 7 Data Sufficiency (DS), 3 Table Analysis (matrix, True/False),
# 4 Graphics Interpretation (cloze; the graph is a pipe table or described in
# words), 3 Two-Part Analysis (matrix: one row per part, or classify-each for
# verbal two-part items) and one 3-item Multi-Source Reasoning set (shared
# stimulus). Domains: gmatDS, gmatTables (TA + GI), gmatTwoPart (TPA + MSR).
T, P = "gmatTables", "gmatTwoPart"
TF = ["True", "False"]
TA_STEM = "For each statement, select True if it is supported by the information in the table. Otherwise select False."
SWN = ["Strengthens", "Weakens", "Neither"]

STIMULI = [
    {"id": "GMAT-MSR1", "title": "Lumen lamp launch", "text":
     "**Email from the marketing director**\n\n"
     "We plan to launch the Lumen desk lamp in three markets in March. Based on our pilot, we expect first-year sales of 18,000 units in Market A, 12,000 units in Market B and 9,000 units in Market C. We will spend \\$4 on advertising for each expected unit in each market.\n\n"
     "**Cost sheet (per unit)**\n\n"
     "| Item | Amount |\n|---|---|\n| Retail price | \\$60 |\n| Retailer margin | 30% of retail price |\n| Manufacturing | \\$22 |\n| Shipping to Market A | \\$3 |\n| Shipping to Market B | \\$4 |\n| Shipping to Market C | \\$6 |\n\n"
     "**Note from finance**\n\n"
     "The board approves a launch in a market only if the expected first-year contribution in that market, after advertising, is at least \\$150,000. Contribution per unit is the retail price minus the retailer margin, manufacturing and shipping."},
    {"id": "GMAT-MSR2", "title": "Warehouse supervisor hiring", "text":
     "**Job posting**\n\n"
     "Northgate Logistics is hiring a warehouse supervisor. Requirements: at least 3 years of supervisory experience, a forklift certification, and availability for night shifts. Preferred: a degree in logistics.\n\n"
     "**Candidates**\n\n"
     "| Candidate | Supervisory experience (years) | Forklift certified | Available nights | Degree |\n|---|---|---|---|---|\n| Ruiz | 5 | Yes | Yes | None |\n| Patel | 2 | Yes | Yes | Logistics |\n| Okafor | 4 | No | Yes | History |\n| Nguyen | 6 | Yes | No | Logistics |\n| Brandt | 3 | Yes | Yes | Logistics |\n\n"
     "**Note from human resources**\n\n"
     "Every candidate who meets all three requirements is invited to a second interview. Okafor's forklift exam is scheduled before the start date, and we will treat it as meeting the certification requirement. Among the candidates invited, anyone with the preferred degree is ranked ahead of anyone without it; candidates with the same degree status are ranked by years of supervisory experience."},
    {"id": "GMAT-MSR3", "title": "Conference venue", "text":
     "**Email from the event planner**\n\n"
     "We need a venue for 180 attendees on June 12, for the whole day, with at least one breakout room. The total budget for the venue and catering together is \\$20,000.\n\n"
     "**Venue quotes**\n\n"
     "| Venue | Capacity | Breakout rooms | Room fee | Catering per person |\n|---|---|---|---|---|\n| Lakeside | 200 | 2 | \\$6,000 | \\$65 |\n| Granary | 160 | 3 | \\$4,000 | \\$55 |\n| Civic Hall | 250 | 0 | \\$3,500 | \\$60 |\n| Riverside | 220 | 1 | \\$8,500 | \\$70 |\n\n"
     "**Venue notes**\n\n"
     "Civic Hall can rent portable partitions that create one breakout room for \\$900. Lakeside is booked until 2 p.m. on June 12. Catering must be ordered for every attendee."},
]


